function building(h){return `<svg viewBox="0 0 400 210" preserveAspectRatio="xMidYMid slice" aria-label="${esc(h.name)} 가상 단지 일러스트" role="img"><rect width="400" height="210" fill="${h.color}"/><circle cx="322" cy="44" r="25" fill="#f8f3dc" opacity=".85"/><path d="M0 156Q90 113 180 160T400 145V210H0Z" fill="#829d7f" opacity=".4"/><rect x="65" y="55" width="88" height="145" fill="#f2f0e3"/><rect x="160" y="85" width="82" height="115" fill="#e8e5d6"/><rect x="249" y="30" width="81" height="170" fill="#f9f7ed"/><path d="M153 55v145h-16V55M242 85v115h-15V85M330 30v170h-14V30" fill="#bcc3ae"/>${[80,105,130,175,200,265,289].map((x,i)=>[75,100,125,150,175].filter(y=>y>(i>4?45:i>2?90:60)).map(y=>`<rect x="${x}" y="${y}" width="11" height="12" rx="1" fill="#728b80" opacity=".65"/>`).join('')).join('')}<rect y="195" width="400" height="15" fill="#8eaa80"/><path d="M19 199v-29M366 199v-35" stroke="#57745a" stroke-width="5"/><circle cx="19" cy="162" r="22" fill="#7b966e"/><circle cx="368" cy="157" r="28" fill="#668b6b"/></svg>`}
function go(route){closeModal();if(location.hash==='#'+route){render();window.scrollTo(0,0)}else location.hash=route}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function closeModal(){$('#modal-root').innerHTML=''}
let modalPreviousFocus;
function modal(html,large=false){modalPreviousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-label="안내" class="modal ${large?'large':''}"><button class="modal-close" data-action="close" aria-label="닫기">×</button>${html}</section></div>`;$('.modal button, .modal input')?.focus()}
function header(route){const links=[['diagnosis','청약 진단'],['homes','집 찾기'],['finance','금융 정보'],['community','커뮤니티']];$('#header').innerHTML=`<div class="nav"><a class="brand" href="#home">청약돼<span>?!</span></a><nav class="nav-links" aria-label="주요 메뉴">${links.map(([id,t])=>`<a href="#${id}" class="${route.startsWith(id)||(id==='homes'&&route.startsWith('detail'))?'active':''}">${t}${id==='community'?'<span class="nav-note">NEW</span>':''}</a>`).join('')}<a href="#dashboard" class="${['dashboard','saved','report','profile'].includes(route)?'active':''}">내 공간</a></nav><div class="nav-account">${state.user?`<button data-action="logout">로그아웃</button><a class="pill" href="#dashboard">${esc(state.user.name)}님</a>`:'<button data-action="login">로그인</button><button class="pill" data-action="signup">회원가입</button>'}</div></div>`}
function houseCard(h,compare=false){return `<article class="house-card"><div class="house-visual"><a href="#detail/${h.id}" tabindex="-1">${building(h)}</a><span class="badge">${h.type}</span><button class="heart ${state.saved.includes(h.id)?'saved':''}" data-action="save-house" data-id="${h.id}" aria-label="${esc(h.name)} ${state.saved.includes(h.id)?'저장 취소':'관심 공고 저장'}">${state.saved.includes(h.id)?'♥':'♡'}</button></div><div class="house-body"><div class="tags"><span class="badge ${h.status==='접수 중'?'orange-badge':'gray'}">${h.status}</span><span class="tag">예시 공고</span></div><a href="#detail/${h.id}"><h3>${h.name}</h3></a><p class="location">${h.loc} · ${h.area}</p><div class="house-bottom"><div><small>${h.type==='공공임대'?'보증금':'분양가'} · 예시</small><br><strong>${money(h.price)}</strong></div><span class="text-link">${h.date}</span></div><div class="tags" style="margin-top:13px">${h.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div>${compare?`<label class="choice-check" style="margin-top:16px"><input type="checkbox" data-action="compare" data-id="${h.id}" ${state.compare.includes(h.id)?'checked':''}> 비교 후보에 담기</label>`:''}</div></article>`}
function home(){return `<section class="hero"><div class="hero-image"></div><div class="hero-body"><div class="eyebrow"><span class="dot"></span> YOUR HOME, YOUR NEXT CHAPTER</div><h1>내 집을 찾는 일,<br><em>내 조건부터</em> 시작해요.</h1><p>흩어진 청약 공고부터 주거 자금, 이웃의 경험까지.<br>지금 나에게 필요한 정보를 한곳에서 만나보세요.</p><div class="hero-actions"><a class="btn orange" href="#diagnosis">1분 진단 시작하기 <span>↗</span></a><a href="#homes" class="hero-link">공고 먼저 둘러보기</a></div><div class="hero-help"><span>✓ 가입 없이 결과 확인</span><span>✓ 저장할 때만 로그인</span></div></div><span class="hero-label">A PLACE TO CALL YOUR OWN</span></section><div class="wrap"><div class="quick-bar">${[['check','청약 진단','내 조건을 차근차근','diagnosis'],['home','집 찾기','청약·임대 공고 한눈에','homes'],['money','금융 정보','내 생활에 맞는 자금 계획','finance'],['chat','우리 이야기','함께 나누는 주거·금융생활','community']].map(([i,t,p,r])=>`<a class="quick" href="#${r}">${icon(i,i==='chat')}<div><strong>${t}</strong><small>${p}</small></div></a>`).join('')}</div><section class="section"><div class="section-head"><div><div class="eyebrow">FIND YOUR PLACE</div><h2>다음 시작을 기다리는 집</h2><p>공고 카드와 상세 화면을 직접 살펴보세요. 아래는 모두 가상 공고입니다.</p></div><a href="#homes" class="text-link">공고 전체 보기 ↗</a></div><div class="grid3">${houses.slice(0,3).map(h=>houseCard(h)).join('')}</div></section><section class="feature-strip"><div class="feature-panel"><div><span class="badge">금융생활</span><h3>집은 찾았는데,<br>자금은 얼마나 필요할까요?</h3><p>내 자금과 필요한 비용을 함께 정리해요.</p><a href="#finance/budget">자금 계획 계산해 보기 ↗</a></div><div class="feature-number">₩</div></div><div class="feature-panel warm"><div><span class="badge orange-badge">시작 가이드</span><h3>처음이라 더 복잡한 청약,<br>하나씩 알아가면 돼요.</h3><p>내 조건을 정리하고 확인할 항목을 찾아요.</p><a href="#diagnosis">내 조건 알아보기 ↗</a></div><div class="feature-number" style="color:#dfc3a9">01</div></div></section><section class="community-preview"><div class="community-intro">${icon('chat',true)}<h3>혼자 고민하지 말고,<br>우리끼리 이야기해요.</h3><p>주거, 금융생활, 커리어까지<br>비슷한 관심사를 가진 사람들과.</p><a href="#community" class="text-link">커뮤니티 둘러보기 ↗</a></div><div>${state.posts.slice(0,4).map(p=>`<a href="#post/${p.id}" class="mini-post"><span class="badge gray">${p.board}</span><span class="post-name">${esc(p.title)}</span><small>♡ ${p.likes}</small></a>`).join('')}</div></section></div>`}
const stages=['기본 정보','주택 소유','가족 구성','청약통장','소득·자산','희망 조건'];
function options(key,values){return `<div class="options">${values.map(v=>`<button class="option ${state.answers[key]===v?'selected':''}" data-action="answer" data-key="${key}" data-value="${v}">${v}</button>`).join('')}</div>`}
function diagnosis(){const a=state.answers;const contents=[`<div class="field"><label>연령대</label>${options('age',['20대','30대','40대 이상'])}</div><div class="field"><label>세대주 여부</label>${options('head',['세대주','세대원','잘 모르겠어요'])}</div><div class="field"><label>혼인 상태</label>${options('marriage',['미혼','신혼','기혼'])}</div><div class="field"><label>현재 거주 지역</label>${options('region',['서울','경기','인천','기타'])}</div>`,`<div class="field"><label>세대의 주택 소유 상태</label>${options('ownership',['무주택','주택 보유','확인 필요'])}<small>실제 진단에서는 세대 구성원의 소유 이력 확인이 필요합니다.</small></div><div class="field"><label for="years">무주택 기간 · 예시 입력</label><input id="years" type="number" min="0" max="30" value="${a.years}" data-answer="years"><small>정확한 산정 시작일은 공고 기준으로 별도 확인합니다.</small></div>`,`<div class="field"><label for="family">부양가족 수 · 본인 제외</label><input id="family" type="number" min="0" max="6" value="${a.family}" data-answer="family"></div><div class="field"><label>미성년 자녀</label>${options('children',['없음','1명','2명 이상'])}</div><div class="callout">가족의 이름이나 주민등록번호는 입력하지 않습니다. 숫자와 조건만으로 흐름을 체험해요.</div>`,`<div class="field"><label for="account">청약통장 가입 기간 · 년</label><input id="account" type="number" min="0" max="30" value="${a.account}" data-answer="account"></div><div class="field"><label for="payments">납입 인정 회차</label><input id="payments" type="number" min="0" max="500" value="${a.payments}" data-answer="payments"><small>실제 인정 회차는 은행에서 확인한 값을 사용합니다.</small></div>`,`<div class="field"><label>소득 기준 확인 상태</label>${options('income',['확인했어요','직접 확인할게요','아직 모르겠어요'])}<small>이번 목업에서는 소득을 이용한 자격 판정을 하지 않습니다.</small></div><div class="field"><label for="assets">주거에 쓸 수 있는 현금 · 만원</label><input id="assets" type="number" min="0" max="1000000" step="100" value="${a.assets}" data-answer="assets"><small>실제 개인정보 대신 예시 숫자로 체험해 주세요.</small></div>`,`<div class="field"><label>희망 지역</label>${options('wish',['서울','경기','인천','전체'])}</div><div class="field"><label>관심 주거 유형</label>${options('type',['공공분양','민간분양','공공임대','전체'])}</div><div class="callout">결과에서는 선택한 지역·유형과 연결된 공고를 보여드려요. 최종 신청 자격을 확정하는 기능은 제공하지 않습니다.</div>`];return `<div class="diagnosis-wrap reveal"><div class="diagnosis-head"><div class="eyebrow" style="justify-content:center">GET TO KNOW YOUR CONDITIONS</div><h1>내 집 찾기, 내 조건부터.</h1><p>예시 정보로 6단계를 체험하세요. 가입 없이 결과를 먼저 확인할 수 있어요.</p></div><div class="stepper">${stages.map((s,i)=>`<button data-action="step" data-id="${i}" class="${i===state.step?'current':i<state.step?'done':''}"><span>${i<state.step?'✓':i+1}</span>${s}</button>`).join('')}</div><div class="progress"><div style="width:${(state.step+1)/6*100}%"></div></div><div class="diagnosis-body"><section class="panel diagnosis-panel"><div class="step-count">STEP 0${state.step+1} / 06</div><h2>${stages[state.step]}</h2><p class="description">내 조건을 알면, 필요한 정보를 더 쉽게 찾을 수 있어요.</p>${contents[state.step]}<div class="step-actions"><button class="btn secondary" data-action="previous" ${state.step===0?'disabled':''}>이전</button><button class="btn" data-action="next">${state.step===5?'진단 결과 보기':'다음'} →</button></div></section><aside class="diagnosis-aside"><h3>이렇게 이어져요</h3><p>입력한 조건은 추천 이유와<br>확인할 항목을 정리하는 데 사용해요.</p><div class="flow-mini"><div>01 내 조건 입력 <span>지금</span></div><div>02 결과 미리보기 <span>가입 없이</span></div><div>03 결과 저장 <span>로그인 후</span></div><div>04 공고·자금 탐색 <span>자유롭게</span></div></div><p>모든 입력은 이 브라우저 안에서만 처리됩니다.</p></aside></div></div>`}
function points(){const a=state.diagnosis||state.answers;const year=Number(a.years)||0;const housing=a.ownership==='무주택'?Math.min(32,year<1?2:Math.floor(year)*2+2):0;const family=Math.min(35,5+(Number(a.family)||0)*5);const account=Math.min(17,(Number(a.account)||0)<1?1:Math.floor(Number(a.account))+2);return{housing,family,account,total:housing+family+account}}
function recommended(){const a=state.diagnosis||state.answers;return houses.filter(h=>(a.wish==='전체'||h.region===a.wish)&&(a.type==='전체'||h.type===a.type))}
function result(){if(!state.diagnosis)return emptyPage('아직 진단 결과가 없어요','예시 정보로 간단한 진단을 먼저 진행해 보세요.','diagnosis','진단 시작하기');const a=state.diagnosis,s=points(),matches=recommended();return `<div class="wrap page reveal"><div class="breadcrumbs">청약 진단 / 결과 미리보기</div><div class="result-banner"><div><div class="eyebrow" style="color:#c1d6c3">YOUR FIRST STEP</div><h2>내 조건이 정리됐어요.</h2><p>${esc(a.age)} · ${esc(a.marriage)} · ${esc(a.ownership)} · ${esc(a.region)} 거주<br>희망 조건: ${esc(a.wish)} · ${esc(a.type)}</p></div><div><small style="color:#c5d7c5">단순 가점 계산 예시</small><div class="score">${s.total}<span> / 84</span></div></div></div><div class="grid2"><section class="panel"><h3>가점은 이렇게 계산했어요</h3><div class="score-breakdown">${[['무주택 기간',s.housing],['부양가족',s.family],['통장 가입 기간',s.account]].map(([t,n])=>`<div><small>${t}</small><b>${n}점</b></div>`).join('')}</div><p class="demo-note">입력값을 단순 산식에 적용한 목업 예시입니다. 연령별 산정·세대원 인정 등 예외 조건을 반영한 실제 자격 판정이 아닙니다.</p><a href="#diagnosis" class="text-link" style="display:block;margin-top:20px">입력 정보 수정 ↗</a></section><section class="panel"><h3>신청 전에 확인할 항목</h3><div class="kv"><span>공고일 기준 세대 정보</span><span class="badge gray">직접 확인</span></div><div class="kv"><span>소득·자산 산정 기준</span><span class="badge gray">직접 확인</span></div><div class="kv"><span>공고별 거주·통장 요건</span><span class="badge gray">원문 확인</span></div></section></div><section class="section"><div class="section-head"><div><h2>희망 조건과 연결된 공고</h2><p>선택한 지역·유형과 일치하는 가상 공고 ${matches.length}건입니다.</p></div></div>${matches.length?`<div class="grid3">${houseCard(matches[0])}<div class="panel" style="display:flex;align-items:center;justify-content:center;text-align:center"><div>${icon('home')}<h3 style="margin:16px 0">전체 공고도 둘러보세요</h3><p style="color:var(--muted);font-size:12px">조건에 맞는 공고가 적으면<br>지역이나 공급 유형을 넓혀볼 수 있어요.</p><a href="#homes" class="btn soft small" style="margin-top:20px">전체 공고 보기</a></div></div></div>`:'<div class="callout">현재 예시 목록에는 일치하는 공고가 없어요. 희망 조건을 바꾸거나 전체 공고를 둘러보세요.</div>'}</section>${state.user?'<div class="join-box"><h2>결과를 내 공간에 저장했어요.</h2><p>관심 공고와 자금 계획을 함께 살펴보세요.</p><a class="btn" href="#dashboard">내 공간으로 →</a></div>':'<div class="join-box"><h2>내 조건을 저장하고, 다음 단계로.</h2><p>로그인하면 진단 결과와 관심 공고를 내 공간에서 이어볼 수 있어요.</p><button class="btn" data-action="signup">결과 저장하고 시작하기 →</button><p style="margin-bottom:0">실제 계정 생성 없이 데모 로그인으로 체험합니다.</p></div>'}</div>`}
function homes(){let list=houses.filter(h=>(state.filterRegion==='전체'||h.region===state.filterRegion)&&(state.filterType==='전체'||h.type===state.filterType)&&`${h.name} ${h.loc}`.includes(state.search));if(state.sort==='price')list.sort((a,b)=>a.price-b.price);return `<div class="wrap page reveal"><div class="page-title"><div class="eyebrow">FIND YOUR PLACE</div><h1>내 생활에 맞는 집 찾기</h1><p>조건을 골라 공고를 살펴보고, 마음에 드는 집은 저장해 두세요.</p></div><div class="filter-layout"><aside class="panel filter-panel"><h3>공고 조건</h3><div class="filter-group"><h3>지역</h3>${['전체','서울','경기','인천'].map(v=>`<label><input type="radio" name="region" value="${v}" data-filter="filterRegion" ${state.filterRegion===v?'checked':''}> ${v}</label>`).join('')}</div><div class="filter-group"><h3>공급 유형</h3>${['전체','공공분양','민간분양','공공임대'].map(v=>`<label><input type="radio" name="type" value="${v}" data-filter="filterType" ${state.filterType===v?'checked':''}> ${v}</label>`).join('')}</div><button class="text-link" data-action="clear-filters" style="margin-top:20px">조건 초기화 ↺</button><p class="filter-help">자격을 확정하는 필터가 아닙니다.<br>공고마다 원문의 요건을 확인하세요.<br><br>목업에서는 가상 단지 6건으로<br>검색·저장·비교를 체험합니다.</p></aside><section><form class="search-row" id="house-search"><input aria-label="공고명 또는 지역 검색" placeholder="공고명 또는 지역을 검색해 보세요" value="${esc(state.search)}"><button class="btn" type="submit">검색</button></form><div class="results-head"><h3>공고 ${list.length}건 <span class="badge gray">모두 예시</span></h3><div class="view-toggle"><button class="chip ${!state.map?'active':''}" data-action="view-list">목록</button><button class="chip ${state.map?'active':''}" data-action="view-map">지도</button><select aria-label="공고 정렬" data-filter="sort"><option value="default">기본 순서</option value="price" ${state.sort==='price'?'selected':''}>비용 낮은순</option></select></div></div>${state.map?mapView(list):list.length?`<div class="list-grid">${list.map(h=>houseCard(h,true)).join('')}</div>`:'<div class="empty"><h3>일치하는 예시 공고가 없어요</h3><p>지역·유형 또는 검색어를 바꿔보세요.</p><button class="btn soft" data-action="clear-filters">조건 초기화</button></div>'}</section></div>${state.compare.length?`<div class="sticky-compare"><span>비교 후보 ${state.compare.length} / 3</span><button class="btn" data-action="compare-open">비교하기 →</button><button data-action="compare-clear" aria-label="비교 후보 초기화">×</button></div>`:''}</div>`}
function mapView(list){return `<div class="map-box"><svg viewBox="0 0 800 500"><rect width="800" height="500" fill="#ecf1e6"/><path d="M-20 410Q200 150 420 275T820 80" fill="none" stroke="#c0dbe1" stroke-width="60"/>${[90,220,350,480,610,740].map(x=>`<path d="M${x} 0v500" stroke="white" stroke-width="16"/>`).join('')}${[60,180,310,440].map(y=>`<path d="M0 ${y}h800" stroke="white" stroke-width="18"/>`).join('')}<rect x="250" y="70" width="90" height="80" rx="18" fill="#c7dabc"/><rect x="630" y="340" width="100" height="70" rx="18" fill="#c7dabc"/></svg>${list.map((h,i)=>`<a class="map-pin" href="#detail/${h.id}" style="left:${15+(i%3)*25}%;top:${18+Math.floor(i/3)*33}%">${h.name}<br>${money(h.price)}</a>`).join('')}<div class="map-label">위치 관계를 설명하는 모식도 · 실제 지도 아님</div></div>`}
function detail(id){const h=houses.find(h=>h.id===Number(id));if(!h)return emptyPage('공고를 찾을 수 없어요','목록에서 공고를 다시 선택해 주세요.','homes','공고 목록');return `<div class="wrap page reveal"><div class="breadcrumbs"><a href="#homes">집 찾기</a> / ${h.region} / 공고 상세</div><div class="detail-layout"><div><div class="detail-title"><div class="tags"><span class="badge">${h.type}</span><span class="badge orange-badge">${h.status}</span><span class="badge gray">가상 공고</span></div><h1>${h.name}</h1><p>${h.loc} · ${h.area}</p></div><div class="detail-cover">${building(h)}</div><nav class="detail-nav"><a href="#detail/${h.id}" data-action="scroll-section" data-target="summary">핵심 정보</a><a href="#detail/${h.id}" data-action="scroll-section" data-target="conditions">확인할 조건</a><a href="#detail/${h.id}" data-action="scroll-section" data-target="transport">교통·생활</a><a href="#detail/${h.id}" data-action="scroll-section" data-target="document">공고문</a></nav><section id="summary" class="panel detail-box"><h3>공고 핵심 정보</h3><div class="facts"><div class="fact"><small>접수 일정 · 예시</small><strong>${h.date}</strong></div><div class="fact"><small>공급 유형</small><strong>${h.type}</strong></div><div class="fact"><small>전용면적</small><strong>${h.area}</strong></div><div class="fact"><small>정보 상태</small><strong>목업용 예시 데이터</strong></div></div><p style="margin-top:20px">선택한 지역과 공급 유형을 기준으로 살펴볼 수 있는 가상 공고입니다. 일정과 비용은 기능 설명용이며 실제 모집 정보가 아닙니다.</p></section><section id="conditions" class="panel detail-box"><h3>내 조건과 함께 확인할 항목</h3>${['무주택·세대 구성 요건','공고일 기준 거주 요건','소득·자산 산정 기준','청약통장 가입·납입 기준'].map(t=>`<div class="kv"><span>${t}</span><span class="badge gray">공고문 확인</span></div>`).join('')}<p class="demo-note">정보가 부족한 항목을 충족·미충족으로 확정하지 않습니다.</p></section><section id="transport" class="panel detail-box"><h3>자주 가는 곳까지 얼마나 걸릴까요?</h3><form id="route-form" class="search-row"><input aria-label="목적지" placeholder="예: 강남역" value="강남역"><button class="btn" type="submit">경로 보기</button></form><div id="route-output"><p>주소·장소 검색 → 좌표 확인 → 대중교통 경로 조회 흐름을 체험해요.</p></div><p class="demo-note">실제 지도·카카오·ODsay 연결 전의 시연 화면입니다.</p></section><section id="document" class="panel detail-box"><h3>원문과 근거를 함께 확인해요</h3><p>정식 서비스에서는 출처, 공고일, 원문 링크와 PDF 페이지를 이 영역에 표시합니다.</p><button class="btn secondary small" data-action="document" data-id="${h.id}" style="margin-top:18px">예시 공고문 보기 ↗</button></section></div><aside class="panel detail-aside"><small>${h.type==='공공임대'?'보증금':'분양가'} · 예시</small><strong class="price">${money(h.price)}</strong><div class="kv"><span>계약금 · 명시값 예시</span><strong>${money(h.deposit)}</strong></div><div class="kv"><span>납부 일정</span><strong>원문 확인 필요</strong></div><button class="btn" data-action="save-house" data-id="${h.id}">${state.saved.includes(h.id)?'♥ 관심 공고에 저장됨':'♡ 관심 공고 저장'}</button><a class="btn secondary" href="#finance/budget/${h.id}">이 공고로 자금 계산</a><a class="btn soft" href="#chat/${h.id}">공고 내용 물어보기</a><p class="fine-print">이 화면은 가상 공고입니다. 실제 청약 신청이나 자격 확정은 진행되지 않습니다.</p></aside></div></div>`}
function emptyPage(title,desc,route,label){return `<div class="wrap page"><div class="empty">${icon('home')}<h3>${title}</h3><p>${desc}</p><a href="#${route}" class="btn">${label}</a></div></div>`}
function dashboard(){if(!state.user)return `<div class="wrap page"><div class="empty">${icon('check')}<h3>내 조건과 관심 공고를 한곳에</h3><p>데모 로그인으로 결과 저장과 내 공간을 체험해 보세요.</p><button class="btn" data-action="login">데모 로그인</button></div></div>`;return `<div class="wrap page reveal"><div class="welcome"><div><div class="eyebrow">MY SPACE</div><h2>${esc(state.user.name)}님, 다음 집을 함께 찾아봐요.</h2><p>${state.diagnosis?'진단 결과를 바탕으로 관심 공고와 자금 계획을 이어보세요.':'아직 진단을 진행하지 않았어요. 내 조건부터 정리해 보세요.'}</p></div><a class="btn secondary small" href="#${state.diagnosis?'result':'diagnosis'}">${state.diagnosis?'진단 결과':'진단 시작'} ↗</a></div><div class="dash-grid"><div><div class="section-head"><h2>관심 공고 <small>${state.saved.length}건</small></h2><a href="#saved" class="text-link">전체 보기 ↗</a></div>${state.saved.length?`<div class="list-grid">${houses.filter(h=>state.saved.includes(h.id)).slice(0,2).map(h=>houseCard(h)).join('')}</div>`:'<div class="empty"><h3>첫 관심 공고를 저장해 보세요</h3><p>공고 카드의 하트를 누르면 이곳에 모입니다.</p><a class="btn soft" href="#homes">집 찾기</a></div>'}<div class="section" style="padding-top:30px"><div class="section-head"><h2>다음으로 해볼 일</h2></div><div class="grid2"><a class="feature-panel" href="#finance/budget"><div><h3>주거 자금 정리</h3><p>보유 현금과 필요한 비용 계산 ↗</p></div>${icon('money')}</a><a class="feature-panel warm" href="#community"><div><h3>이웃의 경험 읽기</h3><p>비슷한 고민 함께 나누기 ↗</p></div>${icon('chat',true)}</a></div></div></div><aside class="dash-aside"><section class="panel"><h3>내 조건 요약</h3>${state.diagnosis?`<div class="kv"><span>희망 지역</span><strong>${esc(state.diagnosis.wish)}</strong></div><div class="kv"><span>주거 유형</span><strong>${esc(state.diagnosis.type)}</strong></div><div class="kv"><span>현금 · 예시 입력</span><strong>${money(state.diagnosis.assets)}</strong></div>`:'<p class="demo-note">진단을 완료하면 조건이 표시됩니다.</p>'}<a href="#profile" class="dash-action">내 정보 관리 <span>→</span></a><a href="#report" class="dash-action">청약 준비 리포트 <span>→</span></a></section><section class="panel"><h3>관심 공고 일정 · 예시</h3>${state.saved.length?houses.filter(h=>state.saved.includes(h.id)).map(h=>`<a href="#detail/${h.id}" class="dash-action"><span>${h.name}<br><small>${h.date}</small></span><span>↗</span></a>`).join(''):'<p class="demo-note">저장한 공고의 접수 일정이 모입니다.</p>'}</section><section class="panel"><h3>관심 금융 정보</h3><p class="demo-note">저장한 상품 ${state.products.length}건</p><a href="#finance" class="dash-action">금융 정보 살펴보기 <span>→</span></a></section></aside></div></div>`}
function savedPage(){if(!state.user)return dashboard();return `<div class="wrap page"><div class="page-title"><div class="eyebrow">SAVED PLACES</div><h1>관심 공고</h1><p>마음에 드는 집을 모아두고 최대 3개까지 비교해 보세요.</p></div>${state.saved.length?`<div class="grid3">${houses.filter(h=>state.saved.includes(h.id)).map(h=>houseCard(h,true)).join('')}</div>`:'<div class="empty"><h3>저장한 공고가 없어요</h3><a href="#homes" class="btn">공고 둘러보기</a></div>'}${state.compare.length?`<div class="sticky-compare"><span>비교 후보 ${state.compare.length} / 3</span><button class="btn" data-action="compare-open">비교하기 →</button></div>`:''}</div>`}
const financials={대출:[['새봄은행','전월세 대출 안내','공개 조건 확인','보증 기관·주택 종류·소득 조건을 확인하는 정보 화면입니다.'],['온빛은행','주택담보대출 안내','상환 방식 살펴보기','고정·변동금리와 상환기간 등 비교 항목을 정리합니다.'],['다온은행','신용대출 안내','심사 항목 알아보기','공개된 기본 정보를 읽고 공식 안내로 이동하는 흐름입니다.']],예적금:[['새봄은행','차곡 정기예금','연 3.0%','12개월 · 기본금리 예시 · 세전'],['온빛은행','매일 조금씩 적금','연 3.5%','12개월 · 기본금리 예시 · 세전'],['다온은행','자유 저축 예금','연 2.8%','6개월 · 기본금리 예시 · 세전']],카드:[['새봄카드','생활의 기본','대중교통 · 통신','전월 실적과 월 할인 한도를 함께 확인하는 카드 예시'],['온빛카드','우리집 생활','마트 · 생활비','생활 분야별 혜택을 비교하는 카드 예시'],['다온카드','가볍게 출발','온라인 · 구독','연회비와 혜택 적용 조건을 확인하는 카드 예시']]};
function finance(sub,id){if(['대출','예적금','카드','보험 안내','자금 계산'].includes(sub))state.finance=sub;if(sub==='budget')state.finance='자금 계산';const tab=state.finance;return `<div class="wrap page reveal"><div class="finance-hero"><div><div class="eyebrow">FINANCE FOR EVERYDAY LIFE</div><h1>내 생활에 맞는 금융 정보</h1><p>주거 자금부터 저축·카드까지, 필요한 정보를 쉽게 살펴보세요.</p></div><div class="big-icon">₩</div></div><div class="subnav">${['대출','예적금','카드','보험 안내','자금 계산'].map(t=>`<button class="chip ${tab===t?'active':''}" data-action="finance-tab" data-value="${t}">${t}</button>`).join('')}</div>${tab==='자금 계산'?budget(id):tab==='보험 안내'?insurance():`<div class="section-head"><div><h2>${tab==='대출'?'어떤 자금이 필요한가요?':tab==='카드'?'주로 어디에 소비하시나요?':'저축 계획을 비교해 보세요'}</h2><p>가상의 기관과 상품으로 화면 구성을 설명합니다. 실제 추천·신청은 진행하지 않아요.</p></div></div>${tab==='카드'?'<div class="subnav">'+['전체','대중교통','마트','온라인'].map(t=>`<button class="chip ${t==='전체'?'active':''}" data-action="card-filter" data-value="${t}">${t}</button>`).join('')+'</div>':''}<div class="grid3" id="product-grid">${productCards(tab)}</div>`}<div class="callout">이 목업의 상품명·금리·혜택은 예시입니다. 실제 서비스에서는 공식 상품 정보의 출처와 확인 시각을 제공하며, 개인별 대출 승인·한도를 확정하지 않습니다.</div></div>`}
function productCards(tab,filter='전체'){const list=financials[tab]||[];return list.filter(p=>filter==='전체'||p.join(' ').includes(filter)).map((p,i)=>`<article class="product-card"><div class="product-top"><div class="product-logo">${p[0][0]}</div><div><h3>${p[0]}</h3><small>가상 기관 · 예시 상품</small></div></div><span class="badge gray">${p[1]}</span><div class="product-number" style="font-size:${tab==='대출'?22:27}px">${p[2]}</div><p>${p[3]}</p><button class="btn secondary" data-action="product" data-tab="${tab}" data-id="${i}">상세 정보 보기 ↗</button></article>`).join('')}
function budget(id){const h=houses.find(h=>h.id===Number(id));const assets=Number(state.diagnosis?.assets||10000);return `<section class="panel"><div class="section-head"><div><h2>주거 자금, 숫자로 정리해요</h2><p>비용과 보유 현금의 단순 차액을 계산합니다.</p></div></div><form id="budget-form" class="calculator"><div><div class="field"><label for="budget-house">공고 선택 · 예시</label><select id="budget-house"><option value="">직접 입력</option>${houses.map(x=>`<option value="${x.id}" ${h?.id===x.id?'selected':''}>${x.name}</option>`).join('')}</select></div><div class="field"><label for="budget-cost">주택 비용 · 만원</label><input id="budget-cost" type="number" min="0" max="1000000" value="${h?.price||38500}"></div><div class="field"><label for="budget-cash">주거에 쓸 수 있는 현금 · 만원</label><input id="budget-cash" type="number" min="0" max="1000000" value="${assets}"></div><button class="btn" type="submit">필요한 추가 자금 계산 →</button></div><div class="calc-result"><span class="badge">단순 차액 계산</span><p style="margin-top:18px">추가로 마련할 자금</p><strong id="budget-output">${money(Math.max(0,(h?.price||38500)-assets))}</strong><p style="font-size:11px;color:var(--muted)">주택 비용 − 보유 현금<br>부대비용·대출 가능액은 포함하지 않습니다.</p></div></form></section>`}
function insurance(){return `<div class="section-head"><div><h2>보험 용어부터 쉽게 알아봐요</h2><p>개인별 보험 가입·보장 분석 없이 기본 개념을 안내합니다.</p></div></div><div class="grid3">${[['shield','보장 범위','무엇을 보장하고, 어떤 경우에 제외되는지 확인하는 항목입니다.'],['money','보험료와 납입기간','매달 납입 금액, 납입기간과 보장기간은 서로 다를 수 있습니다.'],['check','가입 전 체크리스트','갱신 여부, 면책·감액기간, 기존 보장 중복을 함께 확인합니다.']].map(([i,t,d])=>`<article class="panel insurance-card">${icon(i)}<h3>${t}</h3><p>${d}</p><button class="text-link" data-action="insurance" data-value="${t}" style="margin-top:20px">자세히 알아보기 ↗</button></article>`).join('')}</div>`}
const boards=['통합','인기 글','청약·집 구하기','금융생활','취업·커리어','자유'];
function community(){let posts=state.posts.filter(p=>(['통합','인기 글'].includes(state.board)||p.board===state.board)&&(state.ageFilter==='전체 연령'||p.age===state.ageFilter)&&(state.jobFilter==='전체 분야'||p.job===state.jobFilter)&&`${p.title} ${p.body}`.includes(state.boardSearch));if(state.board==='인기 글')posts.sort((a,b)=>b.likes-a.likes);return `<div class="wrap page reveal"><div class="page-title"><div class="eyebrow">OUR LITTLE NEIGHBORHOOD</div><h1>비슷한 고민, 함께 나눠요.</h1><p>집과 금융생활, 취업 이야기까지. 통합 게시판에서 모든 주제의 글을 만나보세요.</p></div><div class="board-layout"><aside class="panel board-sidebar"><h3>함께 보는 공간</h3>${boards.map(b=>`<button class="board-link ${state.board===b?'active':''}" data-action="board" data-value="${b}">${b}</button>`).join('')}<h3>게시판 이용</h3><button class="board-link" data-action="community-rules">이용 안내 ↗</button></aside><section><div class="section-head"><h2>${state.board} <small>${posts.length}개 글</small></h2><button class="btn small" data-action="write">＋ 글쓰기</button></div><form class="search-row" id="board-search"><input aria-label="게시글 검색" placeholder="함께 나누고 싶은 이야기를 검색하세요" value="${esc(state.boardSearch)}"><button class="btn secondary" type="submit">검색</button></form><div class="board-filter"><select aria-label="연령대 필터" data-filter="ageFilter">${['전체 연령','20대','30대','40대 이상'].map(t=>`<option ${t===state.ageFilter?'selected':''}>${t}</option>`).join('')}</select><select aria-label="분야 필터" data-filter="jobFilter">${['전체 분야','일반','은행','보험','카드','데이터'].map(t=>`<option ${t===state.jobFilter?'selected':''}>${t}</option>`).join('')}</select><button class="text-link" data-action="clear-board">초기화</button></div><div class="post-list">${posts.length?posts.map(p=>`<a href="#post/${p.id}" class="post-row"><div style="min-width:0"><div class="tags"><span class="badge gray">${esc(p.board)}</span><span class="tag">${esc(p.age)}</span><span class="tag">${esc(p.job)}</span><span class="tag">예시</span></div><h3>${esc(p.title)}</h3><p>${esc(p.body.split('\n')[0])}</p><div class="post-meta"><span>${esc(p.author)}</span><span>${p.time}</span><span>댓글 ${p.comments.length}</span></div></div><div class="post-score">♡<br>${p.likes}</div></a>`).join(''):'<div class="empty" style="border:0"><h3>이 조건의 글이 아직 없어요</h3><p>필터를 바꾸거나 첫 이야기를 남겨보세요.</p></div>'}</div><p class="demo-note">연령·분야는 예시 프로필 태그입니다. 별도 인증 없이 익명 이용 흐름을 시연합니다.<br>이 목업에서 작성한 글은 다른 방문자에게 공유되지 않고 현재 브라우저에만 저장됩니다.</p></section></div></div>`}
function post(id){const p=state.posts.find(p=>p.id===Number(id));if(!p)return emptyPage('게시글을 찾을 수 없어요','목록에서 다시 선택해 주세요.','community','목록으로');return `<div class="wrap page reveal"><div class="breadcrumbs"><a href="#community">커뮤니티</a> / ${esc(p.board)}</div><article class="panel post-detail"><div class="tags"><span class="badge">${esc(p.board)}</span><span class="tag">${esc(p.age)} · ${esc(p.job)}</span><span class="tag">목업 게시글</span></div><h2>${esc(p.title)}</h2><div class="post-meta"><span>${esc(p.author)}</span><span>${p.time}</span><span>댓글 ${p.comments.length}</span></div><p class="post-content">${esc(p.body)}</p><div style="display:flex;gap:10px"><button class="btn soft small" data-action="like" data-id="${p.id}">♡ 공감 ${p.likes}</button><button class="btn secondary small" data-action="report-post" data-id="${p.id}">신고</button><a href="#community" class="btn secondary small">목록으로</a></div><div class="comments"><h3>댓글 ${p.comments.length}</h3>${p.comments.map(c=>`<div class="comment"><strong>${esc(c.author)}</strong><p>${esc(c.body)}</p></div>`).join('')}<form class="reply-form" id="comment-form" data-id="${p.id}"><input placeholder="이야기를 남겨 주세요" aria-label="댓글" maxlength="1000" required><button class="btn" type="submit">등록</button></form></div></article></div>`}
function chat(id){const h=houses.find(h=>h.id===Number(id))||houses[0];return `<div class="wrap page reveal"><div class="page-title"><div class="eyebrow">ASK WITH CONTEXT</div><h1>공고를 읽다 궁금해졌다면</h1><p>공고 선택 → 질문 → 요약과 근거 확인 흐름을 체험하세요.</p></div><div class="chat-layout"><aside class="panel chat-side"><h3>참조할 공고</h3><select id="chat-house" aria-label="상담 공고">${houses.map(x=>`<option value="${x.id}" ${x.id===h.id?'selected':''}>${x.name}</option>`).join('')}</select><p class="demo-note">현재는 정해진 예시 답변을 보여줍니다. 실제 AI·RAG 호출은 없습니다.</p><h3 style="margin-top:25px">이렇게 물어보세요</h3>${['접수 일정 알려줘','자금은 얼마나 준비해야 해?','신청 전에 무엇을 확인해야 해?'].map(q=>`<button class="chat-prompt" data-action="prompt" data-value="${q}" data-id="${h.id}">${q} ↗</button>`).join('')}</aside><section class="panel chat-panel"><div class="chat-title"><h3>${h.name} · 공고 상담</h3><span class="badge gray">예시 답변</span></div><div class="messages" id="messages"><div class="message assistant">${h.name}의 정보를 함께 살펴볼게요.<br>일정, 비용 또는 확인할 조건을 물어보세요.<span class="source">근거 위치를 보여주는 예시 · 실제 공고문 아님</span></div>${state.messages.map(m=>`<div class="message ${m.role}">${esc(m.text)}${m.role==='assistant'?'<span class="source">근거: 예시 공고 정보 · 실제 PDF 연결 전</span>':''}</div>`).join('')}</div><form id="chat-form" class="chat-form" data-id="${h.id}"><input aria-label="공고 질문" placeholder="예: 신청 전에 어떤 조건을 확인하나요?" maxlength="1000" required><button class="btn" type="submit">보내기 ↑</button></form></section></div></div>`}
function report(){if(!state.user)return dashboard();const a=state.diagnosis;return `<div class="wrap page reveal"><div class="section-head"><div class="page-title" style="margin:0"><div class="eyebrow">YOUR HOME CHECKLIST</div><h1>나의 청약 준비 리포트</h1><p>확인한 조건, 관심 공고와 다음 할 일을 한곳에 정리했어요.</p></div><button class="btn secondary small no-print" data-action="print">PDF로 저장 ↗</button></div><article class="panel"><span class="badge gray">목업 예시 리포트</span><div class="report-section"><h3>01 · 내 조건</h3><p>${a?`${esc(a.age)} · ${esc(a.marriage)} · ${esc(a.ownership)} · 희망 지역 ${esc(a.wish)} · ${esc(a.type)}`:'아직 진단 정보가 없습니다. 진단을 완료해 보세요.'}</p><a class="text-link" href="#diagnosis">정보 확인·수정 ↗</a></div><div class="report-section"><h3>02 · 관심 공고</h3>${state.saved.length?houses.filter(h=>state.saved.includes(h.id)).map(h=>`<div class="kv"><a href="#detail/${h.id}">${h.name} ↗</a><strong>${h.date} · ${money(h.price)}</strong></div>`).join(''):'<p>저장한 공고가 없습니다.</p>'}</div><div class="report-section"><h3>03 · 자금 계획</h3><p>주거에 쓸 수 있는 현금: ${money(a?.assets||0)} · 입력한 예시값</p><p>관심 공고별 납부 일정과 부대비용을 함께 확인해 주세요.</p><a class="text-link" href="#finance/budget">자금 계산하기 ↗</a></div><div class="report-section"><h3>04 · 다음으로 확인할 것</h3><ul class="plain-list"><li>공고일 기준 세대 정보와 주택 소유 이력</li><li>소득·자산 산정 방식과 증빙 서류</li><li>통장 납입 인정 회차와 지역 요건</li><li>접수 마감 시간과 공식 접수처</li></ul></div><p class="demo-note">모든 공고·금액·가점은 체험용 예시입니다. 신청 자격이나 대출 승인 결과를 보장하지 않습니다.</p></article></div>`}
function profile(){if(!state.user)return dashboard();return `<div class="wrap page"><div class="page-title"><h1>내 정보 관리</h1><p>진단 정보와 체험 데이터를 관리합니다.</p></div><div class="panel"><div class="kv"><span>데모 닉네임</span><strong>${esc(state.user.name)}</strong></div><div class="kv"><span>진단 상태</span><strong>${state.diagnosis?'완료':'아직 없음'}</strong></div><div class="kv"><span>관심 공고</span><strong>${state.saved.length}건</strong></div><a class="btn soft" href="#diagnosis" style="margin-top:25px">진단 정보 수정</a><button class="btn secondary" data-action="delete-diagnosis" style="margin:25px 8px 0">진단 정보 삭제</button><p class="demo-note">실제 계정·개인정보는 서버에 저장되지 않습니다.</p></div></div>`}
function preferencesPage(){const p=read('preferences',{교통:3,생활편의:3,교육환경:3,destination:'강남역',time:'60분'});return `<div class="wrap page reveal"><div class="page-title"><div class="eyebrow">MY PRIORITIES</div><h1>나는 어떤 집에서 살고 싶을까요?</h1><p>중요하게 생각하는 기준을 정리해 두세요. 실제 입지 점수를 산정하는 기능은 아닙니다.</p></div><form id="preferences-form" class="panel"><div class="grid3">${['교통','생활편의','교육환경'].map(t=>`<div class="field"><label for="pref-${t}">${t} 중요도</label><input id="pref-${t}" type="range" min="1" max="5" value="${p[t]}"><small>덜 중요 1 · 보통 3 · 매우 중요 5</small></div>`).join('')}</div><div class="form-row"><div class="field"><label for="pref-destination">자주 가는 장소</label><input id="pref-destination" value="${esc(p.destination)}" placeholder="정확한 주소 대신 역 이름도 괜찮아요"></div><div class="field"><label for="pref-time">희망 이동시간</label><select id="pref-time">${['30분','45분','60분','90분'].map(t=>`<option ${t===p.time?'selected':''}>${t}</option>`).join('')}</select></div></div><button class="btn" type="submit">내 집 기준 저장 →</button><div class="callout">저장한 기준은 내 취향을 정리하는 용도입니다. 추천 순위·실제 교통 조회에 반영하는 기능은 후속 연동 항목입니다.</div></form></div>`}
function render(){const raw=location.hash.slice(1)||'home';const [route,arg,id]=raw.split('/');header(route);let html;switch(route){case'diagnosis':html=diagnosis();break;case'result':html=result();break;case'homes':html=homes();break;case'detail':html=detail(arg);break;case'dashboard':html=dashboard();break;case'saved':html=savedPage();break;case'finance':html=finance(decodeURIComponent(arg||''),id);break;case'community':html=community();break;case'post':html=post(arg);break;case'chat':html=chat(arg);break;case'report':html=report();break;case'profile':html=profile();break;case'preferences':html=preferencesPage();break;default:html=home()}$('#app').innerHTML=html;if(route==='dashboard'&&state.user){$('.dash-aside .panel').insertAdjacentHTML('beforeend','<a href="#preferences" class="dash-action">내 집 기준 설정 <span>→</span></a>')}if(route==='homes'){$('.filter-panel').insertAdjacentHTML('beforeend','<a href="#preferences" class="text-link" style="display:block;margin-top:20px">내 집 기준 설정 ↗</a>')}}
let afterLogin=null;
function login(signup=false,callback=null){afterLogin=callback;modal(`<div class="eyebrow">SAVE YOUR NEXT STEP</div><h2>${signup?'내 집 찾기를 이어가요':'다시 만나 반가워요'}</h2><p>닉네임 하나로 데모 이용을 시작하세요.<br>실제 회원가입이나 인증은 진행하지 않습니다.</p><form id="login-form"><div class="field"><label for="nickname">체험용 닉네임</label><input id="nickname" placeholder="예: 새싹" value="새싹" maxlength="12" required></div><button class="btn full" type="submit">${signup?'결과 저장하고 데모 시작':'데모 로그인'} →</button></form><p style="margin-top:18px;margin-bottom:0">진단 결과·관심 공고는 현재 브라우저에만 저장돼요.</p>`)}
function requireLogin(callback){if(state.user){callback();return}login(false,callback)}
function compareModal(){const hs=houses.filter(h=>state.compare.includes(h.id));if(hs.length<2){toast('공고를 2개 이상 골라 주세요.');return}modal(`<div class="eyebrow">COMPARE YOUR OPTIONS</div><h2>관심 공고 비교</h2><p>비용·면적·일정을 같은 기준으로 살펴보세요. 모든 값은 예시입니다.</p><div class="table-wrap"><table><thead><tr><th>비교 항목</th>${hs.map(h=>`<th>${h.name}</th>`).join('')}</tr></thead><tbody>${[['지역',h=>h.region],['공급 유형',h=>h.type],['면적',h=>h.area],['분양가·보증금',h=>money(h.price)],['계약금 예시',h=>money(h.deposit)],['접수 일정 예시',h=>h.date],['강남역까지 예시',h=>h.commute],['신청 자격',()=>'원문 확인 필요']].map(([t,fn])=>`<tr><td>${t}</td>${hs.map(h=>`<td>${fn(h)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`,true)}
function guide(){modal(`<div class="eyebrow">HOW IT WORKS</div><h2>이 목업, 이렇게 체험하세요.</h2><p>각 화면에서 버튼을 누르면 실제 다음 단계로 이어집니다.</p><div class="flow-guide">${[['01','내 조건 진단','6단계 선택 후 결과 확인','diagnosis'],['02','결과·데모 로그인','결과를 확인하고 내 공간에 저장','result'],['03','집 찾기·비교','필터 → 상세 → 하트 저장 → 비교','homes'],['04','금융생활','대출·예적금·카드·자금 계산','finance'],['05','우리 이야기','통합·주제 게시판과 연령·분야 필터','community'],['06','내 공간·리포트','저장한 공고와 준비 항목 확인','dashboard']].map(([n,t,d,r])=>`<button class="flow-card" data-action="guide-go" data-value="${r}"><span class="num">${n}</span><strong>${t} ↗</strong><small>${d}</small></button>`).join('')}</div><p style="margin-bottom:0">공고·금융 데이터·AI 답변은 예시이며, 실제 로그인·심사·API 연동은 없습니다. 작성한 내용은 방문자 간 공유되지 않습니다.</p>`,true)}
function writePost(){requireLogin(()=>modal(`<div class="eyebrow">SHARE YOUR STORY</div><h2>우리 이야기 남기기</h2><p>목업 체험용 글입니다. 현재 브라우저에서만 보여요.</p><form id="post-form"><div class="form-row"><div class="field"><label for="post-board">주제</label><select id="post-board">${boards.slice(2).map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label for="post-age">연령 태그</label><select id="post-age">${['20대','30대','40대 이상'].map(t=>`<option>${t}</option>`).join('')}</select></div></div><div class="field"><label for="post-job">분야 태그</label><select id="post-job">${['일반','은행','보험','카드','데이터'].map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label for="post-title">제목</label><input id="post-title" maxlength="80" required placeholder="함께 나누고 싶은 고민은?"></div><div class="field"><label for="post-body">내용</label><textarea id="post-body" rows="5" maxlength="5000" required placeholder="실명·연락처 등 개인정보는 적지 마세요."></textarea></div><button class="btn full" type="submit">체험 글 등록 →</button></form>`))}
function answerChat(q,id){const h=houses.find(h=>h.id===Number(id))||houses[0];let text;if(/일정|언제|접수/.test(q))text=`${h.name}의 예시 접수 일정은 ${h.date}입니다.\n\n이 일정은 화면 흐름을 설명하는 가상 데이터예요. 정식 서비스에서는 공식 접수 마감 시간과 원문 링크를 함께 확인합니다.`;else if(/돈|자금|대출|금액|비용/.test(q))text=`이 공고의 예시 ${h.type==='공공임대'?'보증금':'분양가'}는 ${money(h.price)}입니다.\n\n자금 계산 화면에서 보유 현금과 차액을 계산할 수 있어요. 대출 승인·한도는 이 화면에서 판단하지 않습니다.`;else text='신청 전에 세대 구성·주택 소유 이력, 소득·자산 기준, 통장 납입 요건을 공고문에서 확인해야 합니다.\n\n이 목업은 자격을 확정하지 않고, 확인할 항목과 근거를 보여주는 흐름을 시연합니다.';state.messages.push({role:'user',text:q},{role:'assistant',text});go('chat/'+h.id);setTimeout(()=>{const m=$('#messages');if(m)m.scrollTop=m.scrollHeight},0)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action,id=Number(b.dataset.id),v=b.dataset.value;switch(act){case'close':closeModal();modalPreviousFocus?.focus();break;case'guide':guide();break;case'guide-go':go(v);break;case'login':login();break;case'signup':login(true);break;case'logout':state.user=null;save('user',null);render();toast('데모 로그아웃했어요.');break;case'step':state.step=id;render();break;case'answer':state.answers[b.dataset.key]=v;render();break;case'previous':if(state.step>0){state.step--;render()}break;case'next':if(state.step<5){state.step++;render();window.scrollTo(0,0)}else{state.diagnosis={...state.answers};save('diagnosis',state.diagnosis);go('result')}break;case'save-house':requireLogin(()=>{state.saved=state.saved.includes(id)?state.saved.filter(n=>n!==id):[...state.saved,id];save('saved',state.saved);render();toast(state.saved.includes(id)?'관심 공고에 저장했어요.':'저장을 취소했어요.')});break;case'compare-open':compareModal();break;case'compare-clear':state.compare=[];render();break;case'clear-filters':state.filterRegion=state.filterType='전체';state.search='';render();break;case'view-map':state.map=true;render();break;case'view-list':state.map=false;render();break;case'scroll-section':e.preventDefault();$('#'+b.dataset.target)?.scrollIntoView({behavior:'smooth'});break;case'document':{const h=houses.find(h=>h.id===id);modal(`<span class="badge gray">공고문 UI 예시</span><h2 style="margin-top:15px">${h.name}</h2><p>이 단지는 가상 단지이며 원문 PDF는 존재하지 않습니다.</p><div class="panel" style="background:var(--paper)"><h3>공고문 근거 표시 영역</h3><ul class="plain-list"><li>일정: ${h.date} · 예시</li><li>면적: ${h.area}</li><li>비용: ${money(h.price)} · 예시</li></ul><p style="margin:15px 0 0">정식 서비스에서는 파일명·출처·확인일·페이지 번호와 실제 원문을 연결합니다.</p></div>`);break}case'finance-tab':state.finance=v;go('finance');break;case'card-filter':document.querySelectorAll('[data-action="card-filter"]').forEach(x=>x.classList.toggle('active',x.dataset.value===v));$('#product-grid').innerHTML=productCards('카드',v);break;case'product':{const p=financials[b.dataset.tab][id];modal(`<span class="badge gray">가상 상품 · 화면 예시</span><h2 style="margin-top:15px">${p[1]}</h2><p>${p[0]} · ${p[3]}</p><div class="kv"><span>요약 정보</span><strong>${p[2]}</strong></div><div class="kv"><span>비교할 항목</span><strong>비용·기간·적용 조건</strong></div><div class="kv"><span>정보 상태</span><strong>공식 상품 연결 전</strong></div><p style="margin-top:20px">실제 금리·혜택은 제공하지 않습니다. 상세 조건과 출처를 확인한 뒤 관심 정보로 저장하는 흐름입니다.</p><button class="btn full" data-action="save-product" data-value="${p[1]}">관심 정보 저장</button>`);break}case'save-product':requireLogin(()=>{if(!state.products.includes(v))state.products.push(v);save('products',state.products);closeModal();toast('관심 금융 정보에 저장했어요.')});break;case'insurance':modal(`<div class="eyebrow">INSURANCE BASICS</div><h2>${esc(v)}</h2><p>보험을 읽을 때 확인할 기본 개념을 정리합니다.</p><ul class="plain-list"><li>상품설명서의 보장 범위와 제외 항목</li><li>갱신 여부와 보험료 변동 가능성</li><li>납입기간·보장기간·해지 조건</li><li>기존 보험과 보장 중복 여부</li></ul><p style="margin-top:20px;margin-bottom:0">개별 보험 가입 권유나 건강 상태 분석은 제공하지 않습니다.</p>`);break;case'board':state.board=v;render();break;case'clear-board':state.ageFilter='전체 연령';state.jobFilter='전체 분야';state.boardSearch='';render();break;case'write':writePost();break;case'community-rules':modal('<h2>함께 쓰는 공간의 약속</h2><p>익명으로 편하게 이야기하되 서로 존중해 주세요.</p><ul class="plain-list"><li>개인정보·타인의 실명·연락처를 공개하지 않아요.</li><li>대출 모집·상품 판매·투자 권유 글은 올리지 않아요.</li><li>비방·혐오·허위 정보는 신고 대상입니다.</li><li>연령·분야 태그는 자율 선택이며 인증을 의미하지 않습니다.</li></ul><p class="demo-note">이 목업의 신고·차단은 화면 예시이며 운영 서버와 연결되어 있지 않습니다.</p>');break;case'like':{const p=state.posts.find(p=>p.id===id);requireLogin(()=>{const liked=read('liked',[]);if(liked.includes(id)){toast('이미 공감한 글이에요.');return}p.likes++;save('liked',[...liked,id]);save('posts',state.posts);render()});break}case'report-post':modal(`<h2>게시글 신고</h2><p>신고 화면을 체험합니다. 운영자에게 실제 전달되지 않습니다.</p><select id="report-reason" aria-label="신고 사유"><option>금융 광고·사기 의심</option><option>개인정보 노출</option><option>비방·혐오 표현</option><option>기타</option></select><button class="btn full" style="margin-top:20px" data-action="send-report">신고 접수 체험</button>`);break;case'send-report':closeModal();toast('신고 접수 화면을 체험했어요. 실제 전송은 없습니다.');break;case'prompt':answerChat(v,id);break;case'print':window.print();break;case'delete-diagnosis':state.diagnosis=null;save('diagnosis',null);render();toast('이 브라우저의 진단 정보를 삭제했어요.');break;case'reset':modal('<h2>체험 데이터를 초기화할까요?</h2><p>현재 브라우저의 데모 로그인·진단·저장 공고·작성 글이 초기화됩니다.</p><button class="btn full" data-action="reset-confirm">체험 초기화</button>');break;case'reset-confirm':Object.keys(localStorage).filter(k=>k.startsWith('cydemo-')).forEach(k=>localStorage.removeItem(k));location.hash='home';location.reload();break;}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.answer){state.answers[el.dataset.answer]=Math.max(Number(el.min||0),Math.min(Number(el.max||1e9),Number(el.value)||0));el.value=state.answers[el.dataset.answer]}if(el.dataset.filter){state[el.dataset.filter]=el.value;render()}if(el.dataset.action==='compare'){const id=Number(el.dataset.id);if(el.checked){if(state.compare.length>=3){el.checked=false;toast('비교는 최대 3개까지 가능해요.');return}state.compare.push(id)}else state.compare=state.compare.filter(n=>n!==id);render()}if(el.id==='budget-house'){const h=houses.find(x=>x.id===Number(el.value));if(h)$('#budget-cost').value=h.price;calcBudget()}if(['budget-cost','budget-cash'].includes(el.id))calcBudget();if(el.id==='chat-house'){state.messages=[];go('chat/'+el.value)}});
function calcBudget(){const cost=Number($('#budget-cost').value)||0,cash=Number($('#budget-cash').value)||0;$('#budget-output').textContent=money(Math.max(0,cost-cash))}
document.addEventListener('submit',e=>{const form=e.target;e.preventDefault();switch(form.id){case'login-form':{state.user={name:$('#nickname').value.trim()||'새싹'};save('user',state.user);closeModal();const cb=afterLogin;afterLogin=null;if(cb){cb()}else go('dashboard');toast('데모 로그인 완료! 내 공간에서 이어보세요.');break}case'house-search':state.search=form.querySelector('input').value.trim();render();break;case'board-search':state.boardSearch=form.querySelector('input').value.trim();render();break;case'budget-form':calcBudget();toast('단순 차액을 계산했어요.');break;case'route-form':{const id=Number(location.hash.split('/')[1]),h=houses.find(x=>x.id===id),dest=form.querySelector('input').value.trim();$('#route-output').innerHTML=`<div class="route-result"><span class="badge gray">예상 경로 · 시연 데이터</span><p>${h.name} → ${esc(dest||'강남역')}</p><strong>약 ${h.commute}</strong><p>도보 → 버스 또는 지하철 → 환승 → 도보</p><small>실제 경로·정류장·시각은 API 연결 후 표시됩니다.</small></div>`;break}case'post-form':{const p={id:Date.now(),board:$('#post-board').value,age:$('#post-age').value,job:$('#post-job').value,title:$('#post-title').value.trim(),body:$('#post-body').value.trim(),author:'익명 '+state.user.name,likes:0,comments:[],time:'방금'};if(!p.title||!p.body){toast('제목과 내용을 입력해 주세요.');return}state.posts.unshift(p);save('posts',state.posts);go('post/'+p.id);toast('체험 글을 이 브라우저에 저장했어요.');break}case'comment-form':{const body=form.querySelector('input').value.trim(),id=Number(form.dataset.id);if(!body)return;requireLogin(()=>{state.posts.find(p=>p.id===id).comments.push({author:'익명 '+state.user.name,body});save('posts',state.posts);render();toast('댓글을 이 브라우저에 저장했어요.')});break}case'chat-form':answerChat(form.querySelector('input').value.trim(),form.dataset.id);break;}});
document.addEventListener('keydown',e=>{const dialog=$('.modal');if(!dialog)return;if(e.key==='Escape'){closeModal();modalPreviousFocus?.focus()}if(e.key==='Tab'){const nodes=[...dialog.querySelectorAll('button,a,input,textarea,select')].filter(n=>!n.disabled);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
document.addEventListener('submit',e=>{if(e.target.id!=='preferences-form')return;e.preventDefault();const p={};for(const t of ['교통','생활편의','교육환경'])p[t]=Number($('#pref-'+t).value);p.destination=$('#pref-destination').value.trim();p.time=$('#pref-time').value;save('preferences',p);toast('내 집 기준을 이 브라우저에 저장했어요.');});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
render();
